import math

solutions = []
limit = 10

for a in range(limit + 1):
    for b in range(limit + 1):
        # Calculate the expression: 2^a * 5^b + 625
        term = (2**a) * (5**b) + 625

        # Check if term is a perfect square
        N = int(math.isqrt(term)) # math.isqrt is available in Python 3.8+

        if N * N == term:
            solutions.append((a, b, N))

print("Found solutions (a, b, N):")
for sol in solutions:
    print(sol)

# Also check if the solutions found in previous notes are covered
expected_solutions = [(3, 4, 75), (4, 5, 225)]
print("\nChecking against known solutions:")
for exp_sol in expected_solutions:
    if exp_sol in solutions:
        print(f"{exp_sol} found.")
    else:
        print(f"{exp_sol} NOT found.")
